CreateAgent.input:
POST / HTTP/1.1
Host: ags.tencentcloudapi.com
Content-Type: application/json
X-TC-Action: CreateAgent
<公共请求参数>

{
    "AgentName": "example-agent",
    "AgentType": "CLOUD",
    "InitialVersion": "v1",
    "AgentConfig": {
        "Image": "example.com/agent-engine/example-agent:v1",
        "Command": [
            "/usr/local/bin/example-agent"
        ],
        "Args": [
            "serve",
            "--port",
            "8080"
        ],
        "Env": [
            {
                "Name": "EXAMPLE_LOG_LEVEL",
                "Value": "info"
            }
        ],
        "Resources": {
            "CPU": "1000m",
            "Memory": "512Mi"
        },
        "Ports": [
            {
                "Name": "http",
                "Port": 8080,
                "Protocol": "TCP"
            }
        ],
        "HealthCheck": {
            "HttpGet": {
                "Path": "/healthz",
                "Port": 8080,
                "Scheme": "HTTP"
            }
        }
    },
    "ProviderConfig": {
        "ProviderKind": "TENCENT_AGS",
        "TencentAGS": {
            "RoleArn": "qcs::cam::uin/123456789012:roleName/example-agent-engine-role",
            "ImageRegistryType": "personal",
            "NetworkConfiguration": {
                "NetworkMode": "PUBLIC"
            }
        }
    },
    "DefaultWorkspaceTemplateId": "wst-example"
}

